-- Modify "case_inquiries" table
ALTER TABLE "seller"."case_inquiries" DROP CONSTRAINT "case_inquiries_reply_check", ADD CONSTRAINT "case_inquiries_reply_check" CHECK ((((reply_body IS NULL) AND (reply_channel IS NULL) AND (reply_received_at IS NULL) AND (reply_recorded_at IS NULL) AND (reply_recorded_by_admin_id IS NULL) AND (replied_by_account_id IS NULL)) OR ((char_length(reply_body) >= 1) AND (char_length(reply_body) <= 4000) AND (reply_received_at >= created_at) AND (reply_recorded_at >= reply_received_at) AND (((reply_channel = ANY (ARRAY['PHONE'::text, 'EMAIL'::text, 'MESSAGING'::text, 'OTHER'::text])) AND (reply_recorded_by_admin_id > 0) AND (replied_by_account_id IS NULL)) OR ((reply_channel = 'SELLER_CENTER'::text) AND (replied_by_account_id > 0) AND (reply_recorded_by_admin_id IS NULL))))) IS TRUE), ADD COLUMN "replied_by_account_id" bigint NULL;
